from collections import deque

class Solution:
    def largestPathValue(self, colors: str, edges: list[list[int]]) -> int:
        n = len(colors)
        adj = [[] for _ in range(n)]
        in_degree = [0] * n
        for u, v in edges:
            adj[u].append(v)
            in_degree[v] += 1

        q = deque([i for i in range(n) if in_degree[i] == 0])
        dp = [[0] * 26 for _ in range(n)]
        for i in range(n):
            dp[i][ord(colors[i]) - ord('a')] = 1

        visited = 0
        ans = 0

        while q:
            u = q.popleft()
            visited += 1
            ans = max(ans, max(dp[u]))

            for v in adj[u]:
                v_col = ord(colors[v]) - ord('a')
                for c in range(26):
                    cand = dp[u][c] + (1 if c == v_col else 0)
                    if cand > dp[v][c]:
                        dp[v][c] = cand
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    q.append(v)

        return ans if visited == n else -1

class Solution {
public:
    int largestPathValue(string colors, vector<vector<int>>& edges) {
        int n = colors.size();
        vector<vector<int>> adj(n);
        vector<int> inDegree(n, 0);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            inDegree[e[1]]++;
        }

        queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (inDegree[i] == 0) q.push(i);
        }

        vector<vector<int>> dp(n, vector<int>(26, 0));
        for (int i = 0; i < n; ++i) {
            dp[i][colors[i] - 'a'] = 1;
        }

        int visited = 0, ans = 0;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            visited++;
            for (int c = 0; c < 26; ++c) ans = max(ans, dp[u][c]);

            for (int v : adj[u]) {
                int vCol = colors[v] - 'a';
                for (int c = 0; c < 26; ++c) {
                    dp[v][c] = max(dp[v][c], dp[u][c] + (c == vCol ? 1 : 0));
                }
                if (--inDegree[v] == 0) {
                    q.push(v);
                }
            }
        }
        return (visited == n) ? ans : -1;
    }
