import java.util.*;

class Solution {
    public int largestPathValue(String colors, int[][] edges) {
        int n = colors.length();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        int[] inDegree = new int[n];
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            inDegree[e[1]]++;
        }

        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; ++i) {
            if (inDegree[i] == 0) q.offer(i);
        }

        int[][] dp = new int[n][26];
        for (int i = 0; i < n; ++i) {
            dp[i][colors.charAt(i) - 'a'] = 1;
        }

        int visited = 0, ans = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            visited++;
            for (int c = 0; c < 26; ++c) ans = Math.max(ans, dp[u][c]);

            for (int v : adj.get(u)) {
                int vCol = colors.charAt(v) - 'a';
                for (int c = 0; c < 26; ++c) {
                    dp[v][c] = Math.max(dp[v][c], dp[u][c] + (c == vCol ? 1 : 0));
                }
                if (--inDegree[v] == 0) {
                    q.offer(v);
                }
            }
        }
        return (visited == n) ? ans : -1;
    }
}

/**
 * @param {string} colors
 * @param {number[][]} edges
 * @return {number}
