var largestPathValue = function(colors, edges) {
    const n = colors.length;
    const adj = Array.from({ length: n }, () => []);
    const inDegree = Array(n).fill(0);
    for (const [u, v] of edges) {
        adj[u].push(v);
        inDegree[v]++;
    }

    const q = [];
    for (let i = 0; i < n; ++i) {
        if (inDegree[i] === 0) q.push(i);
    }

    const dp = Array.from({ length: n }, () => Array(26).fill(0));
    for (let i = 0; i < n; ++i) {
        dp[i][colors.charCodeAt(i) - 97] = 1;
    }

    let head = 0, visited = 0, ans = 0;
    while (head < q.length) {
        const u = q[head++];
        visited++;
        for (let c = 0; c < 26; ++c) if (dp[u][c] > ans) ans = dp[u][c];

        for (const v of adj[u]) {
            const vCol = colors.charCodeAt(v) - 97;
            for (let c = 0; c < 26; ++c) {
                const cand = dp[u][c] + (c === vCol ? 1 : 0);
                if (cand > dp[v][c]) dp[v][c] = cand;
            }
            if (--inDegree[v] === 0) {
                q.push(v);
            }
        }
    }
    return visited === n ? ans : -1;
};
